{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlook at dusk; ink-stained coat flapping, brass compass spinning toward distant broken spires.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp wakes with a warning.",
      "visual_description": "Close-up of an oil lamp on a stone marker, single eye blooming in the flame, casting long shadows across cracked cobblestones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox sniffs out a hidden path.",
      "visual_description": "A small clockwork fox with key-wind tail and blue glass eyes pawing at a half-buried sewer grate beside fallen royal banners.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives through a shattered window.",
      "visual_description": "A figure in a clear diving helmet steps out of a tall broken windowpane, coat shimmering with reflected city fires.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the looming castle gates.",
      "visual_description": "Massive iron gates twisted off their hinges, banners shredded; the four figures huddle in the rubble shadow at the threshold.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Oracle lamp warns of the cursed tower ahead.",
      "visual_description": "A leaning tower wreathed in green vapor; the lamp's flame-eye narrows, projecting warning glyphs onto Mara's outstretched map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin fox slips past an armored patrol.",
      "visual_description": "Empty enchanted suits of armor clattering along a courtyard; the metal fox darts between their boots, tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The sleeping tax collector blocks the archive door.",
      "visual_description": "A plump official slumped against a heavy oak door, ledger book as pillow, stamped papers stuck to his sleeves, snoring loudly.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara forges a stamp to bypass the bureaucrat.",
      "visual_description": "Mara presses a hastily inked seal onto a fluttering paper while the official mumbles in his sleep, brass compass dangling.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a winged beast echo from the rooftops.",
      "visual_description": "Huge clawed shadow gliding across moonlit shattered rooftops; the team flattens against a chimney, tin fox's eyes glowing wary.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened townsfolk whisper from a barred window.",
      "visual_description": "Pale faces pressed behind iron bars in a basement window; Mara kneels to listen, lamp casting warm gold onto the cobbles.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Glass diver swims through a stained-glass window.",
      "visual_description": "The rescuer dives headfirst into a cathedral window as if into water, colored shards rippling around the diving helmet.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the cursed tower, a magic door bars the way.",
      "visual_description": "A door inlaid with shifting silver runes; tin fox sniffs the seam while the lamp's eye projects a key-shaped beam.",
      "characters": ["tin_fox", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The captive is found within a mirrored cell.",
      "visual_description": "A small chamber lined with cracked mirrors; the glass diver reaches a gloved hand toward a trembling reflection that reaches back.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Alarm bells ring as patrols converge.",
      "visual_description": "Empty armor clanging through smoke-filled halls; Mara waves the team into a side corridor, compass needle spinning wildly.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector trips up the pursuers.",
      "visual_description": "The dozing official tumbles from a doorway, ledger and papers flying into the path of clattering armored pursuers.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the cracking bridge.",
      "visual_description": "A long stone bridge over a glowing chasm, stones falling away behind their heels; lamp held high, tin fox sprinting ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far cliff, the team looks back at the ruined city.",
      "visual_description": "Dawn light over distant broken spires; the four rescuers stand on a windy bluff, banners of the dead city fluttering far below.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

